insert into public.translations (locale, key, value) values
  ('pt-BR', 'error.screen.title', $json$"Não foi possível mostrar esta tela"$json$::jsonb),
  ('en', 'error.screen.title', $json$"This screen could not be shown"$json$::jsonb),
  ('es', 'error.screen.title', $json$"No se pudo mostrar esta pantalla"$json$::jsonb),
  ('zh-CN', 'error.screen.title', $json$"无法显示此页面"$json$::jsonb),
  ('hi', 'error.screen.title', $json$"यह स्क्रीन दिखाई नहीं जा सकी"$json$::jsonb),
  ('ar', 'error.screen.title', $json$"تعذّر عرض هذه الشاشة"$json$::jsonb),
  ('fr', 'error.screen.title', $json$"Impossible d’afficher cet écran"$json$::jsonb),
  ('ru', 'error.screen.title', $json$"Не удалось показать этот экран"$json$::jsonb),
  ('ja', 'error.screen.title', $json$"この画面を表示できませんでした"$json$::jsonb),
  ('de', 'error.screen.title', $json$"Dieser Bildschirm konnte nicht angezeigt werden"$json$::jsonb),
  ('pt-BR', 'error.screen.retry', $json$"Tentar de novo"$json$::jsonb),
  ('en', 'error.screen.retry', $json$"Try again"$json$::jsonb),
  ('es', 'error.screen.retry', $json$"Intentar de nuevo"$json$::jsonb),
  ('zh-CN', 'error.screen.retry', $json$"重试"$json$::jsonb),
  ('hi', 'error.screen.retry', $json$"फिर से कोशिश करें"$json$::jsonb),
  ('ar', 'error.screen.retry', $json$"حاول مرة أخرى"$json$::jsonb),
  ('fr', 'error.screen.retry', $json$"Réessayer"$json$::jsonb),
  ('ru', 'error.screen.retry', $json$"Попробовать снова"$json$::jsonb),
  ('ja', 'error.screen.retry', $json$"もう一度試す"$json$::jsonb),
  ('de', 'error.screen.retry', $json$"Erneut versuchen"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.syncRefresh.title', $json$"O que sincroniza aparece sozinho"$json$::jsonb),
  ('en', 'whatsNew.item.syncRefresh.title', $json$"What syncs shows up by itself"$json$::jsonb),
  ('es', 'whatsNew.item.syncRefresh.title', $json$"Lo que se sincroniza aparece solo"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.syncRefresh.title', $json$"同步的内容会自动显示"$json$::jsonb),
  ('hi', 'whatsNew.item.syncRefresh.title', $json$"जो सिंक होता है, वह अपने-आप दिखता है"$json$::jsonb),
  ('ar', 'whatsNew.item.syncRefresh.title', $json$"ما تتم مزامنته يظهر تلقائيًا"$json$::jsonb),
  ('fr', 'whatsNew.item.syncRefresh.title', $json$"Ce qui se synchronise apparaît tout seul"$json$::jsonb),
  ('ru', 'whatsNew.item.syncRefresh.title', $json$"Синхронизированное появляется само"$json$::jsonb),
  ('ja', 'whatsNew.item.syncRefresh.title', $json$"同期した内容が自動で表示されるように"$json$::jsonb),
  ('de', 'whatsNew.item.syncRefresh.title', $json$"Was synchronisiert wird, erscheint von selbst"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.syncRefresh.detail', $json$"O que outro computador ou o site gravou (projetos, chats, respostas, configurações, mods) só aparecia quando outra coisa relia a tela. Num computador novo, a lista de projetos ficava vazia depois do login. Agora a tela se relê sozinha quando a sincronização traz novidade."$json$::jsonb),
  ('en', 'whatsNew.item.syncRefresh.detail', $json$"What another computer or the site wrote (projects, chats, answers, settings, mods) only appeared after something else reloaded the screen. On a new computer, the project list stayed empty after signing in. Now the screen reloads by itself when the sync brings something new."$json$::jsonb),
  ('es', 'whatsNew.item.syncRefresh.detail', $json$"Lo que otro equipo o el sitio escribió (proyectos, chats, respuestas, configuración, mods) solo aparecía cuando algo más recargaba la pantalla. En un equipo nuevo, la lista de proyectos quedaba vacía después de iniciar sesión. Ahora la pantalla se recarga sola cuando la sincronización trae algo nuevo."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.syncRefresh.detail', $json$"另一台计算机或网站写入的内容（项目、聊天、回答、设置、模组）以前只有在别的操作重新加载界面时才会出现。在新计算机上，登录后项目列表一直是空的。现在同步带来新内容时，界面会自动重新加载。"$json$::jsonb),
  ('hi', 'whatsNew.item.syncRefresh.detail', $json$"दूसरे कंप्यूटर या साइट ने जो लिखा (प्रोजेक्ट, चैट, जवाब, सेटिंग्स, मॉड), वह तभी दिखता था जब कोई और चीज़ स्क्रीन को फिर से लोड करती। नए कंप्यूटर पर साइन इन के बाद प्रोजेक्ट की सूची खाली रहती थी। अब सिंक कुछ नया लाता है तो स्क्रीन अपने-आप फिर से लोड होती है।"$json$::jsonb),
  ('ar', 'whatsNew.item.syncRefresh.detail', $json$"ما كتبه حاسوب آخر أو الموقع (المشاريع والمحادثات والردود والإعدادات والإضافات) لم يكن يظهر إلا عندما يعيد شيء آخر تحميل الشاشة. وعلى حاسوب جديد كانت قائمة المشاريع تبقى فارغة بعد تسجيل الدخول. الآن تعيد الشاشة تحميل نفسها عندما تأتي المزامنة بجديد."$json$::jsonb),
  ('fr', 'whatsNew.item.syncRefresh.detail', $json$"Ce qu’un autre ordinateur ou le site avait écrit (projets, chats, réponses, configuration, mods) n’apparaissait que lorsque autre chose rechargeait l’écran. Sur un nouvel ordinateur, la liste des projets restait vide après la connexion. Désormais, l’écran se recharge tout seul quand la synchronisation apporte du nouveau."$json$::jsonb),
  ('ru', 'whatsNew.item.syncRefresh.detail', $json$"То, что записал другой компьютер или сайт (проекты, чаты, ответы, настройки, моды), появлялось только тогда, когда экран перезагружало что-то другое. На новом компьютере список проектов оставался пустым после входа. Теперь экран сам перезагружается, когда синхронизация приносит что-то новое."$json$::jsonb),
  ('ja', 'whatsNew.item.syncRefresh.detail', $json$"別のコンピューターやサイトが書き込んだもの（プロジェクト、チャット、回答、設定、Mod）は、ほかの操作で画面が再読み込みされるまで表示されませんでした。新しいコンピューターでは、サインイン後もプロジェクト一覧が空のままでした。今後は、同期で新しい内容が届くと画面が自動で再読み込みされます。"$json$::jsonb),
  ('de', 'whatsNew.item.syncRefresh.detail', $json$"Was ein anderer Computer oder die Website geschrieben hatte (Projekte, Chats, Antworten, Einstellungen, Mods), erschien erst, wenn etwas anderes den Bildschirm neu lud. Auf einem neuen Computer blieb die Projektliste nach der Anmeldung leer. Jetzt lädt sich der Bildschirm von selbst neu, wenn die Synchronisierung etwas Neues bringt."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.syncedHistoryQuiet.title', $json$"Sem enxurrada de notificações num computador novo"$json$::jsonb),
  ('en', 'whatsNew.item.syncedHistoryQuiet.title', $json$"No flood of notifications on a new computer"$json$::jsonb),
  ('es', 'whatsNew.item.syncedHistoryQuiet.title', $json$"Sin avalancha de notificaciones en un equipo nuevo"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.syncedHistoryQuiet.title', $json$"新计算机上不再涌出大量通知"$json$::jsonb),
  ('hi', 'whatsNew.item.syncedHistoryQuiet.title', $json$"नए कंप्यूटर पर सूचनाओं की बाढ़ नहीं"$json$::jsonb),
  ('ar', 'whatsNew.item.syncedHistoryQuiet.title', $json$"لا سيل من الإشعارات على حاسوب جديد"$json$::jsonb),
  ('fr', 'whatsNew.item.syncedHistoryQuiet.title', $json$"Plus d’avalanche de notifications sur un nouvel ordinateur"$json$::jsonb),
  ('ru', 'whatsNew.item.syncedHistoryQuiet.title', $json$"Никакой лавины уведомлений на новом компьютере"$json$::jsonb),
  ('ja', 'whatsNew.item.syncedHistoryQuiet.title', $json$"新しいコンピューターで通知が殺到しなくなりました"$json$::jsonb),
  ('de', 'whatsNew.item.syncedHistoryQuiet.title', $json$"Keine Flut von Benachrichtigungen auf einem neuen Computer"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.syncedHistoryQuiet.detail', $json$"Quando um computador novo baixava o histórico, cada resposta antiga virava uma notificação de uma vez. Agora só os pedidos feitos neste computador notificam; o que chega de outro computador pela sincronização, não."$json$::jsonb),
  ('en', 'whatsNew.item.syncedHistoryQuiet.detail', $json$"When a new computer downloaded the history, every past answer became a notification at once. Now only the requests made on this computer notify; what arrives from another computer through sync does not."$json$::jsonb),
  ('es', 'whatsNew.item.syncedHistoryQuiet.detail', $json$"Cuando un equipo nuevo descargaba el historial, cada respuesta antigua se convertía en una notificación a la vez. Ahora solo notifican las solicitudes hechas en este equipo; lo que llega de otro equipo por la sincronización, no."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.syncedHistoryQuiet.detail', $json$"新计算机下载历史记录时，每个旧回答都会同时变成一条通知。现在只有在这台计算机上发出的请求才会通知；通过同步从另一台计算机传来的内容不会。"$json$::jsonb),
  ('hi', 'whatsNew.item.syncedHistoryQuiet.detail', $json$"जब नया कंप्यूटर इतिहास डाउनलोड करता था, तो हर पुराना जवाब एक साथ सूचना बन जाता था। अब सिर्फ़ इस कंप्यूटर पर किए गए अनुरोध सूचना देते हैं; सिंक के ज़रिए दूसरे कंप्यूटर से आने वाली चीज़ें नहीं।"$json$::jsonb),
  ('ar', 'whatsNew.item.syncedHistoryQuiet.detail', $json$"عندما كان حاسوب جديد ينزّل السجل، كان كل رد قديم يتحول إلى إشعار دفعة واحدة. الآن لا تُرسل إشعارات إلا للطلبات التي أُجريت على هذا الحاسوب؛ أما ما يصل من حاسوب آخر عبر المزامنة فلا."$json$::jsonb),
  ('fr', 'whatsNew.item.syncedHistoryQuiet.detail', $json$"Quand un nouvel ordinateur téléchargeait l’historique, chaque ancienne réponse devenait une notification d’un coup. Désormais, seules les demandes faites sur cet ordinateur notifient ; ce qui arrive d’un autre ordinateur par la synchronisation, non."$json$::jsonb),
  ('ru', 'whatsNew.item.syncedHistoryQuiet.detail', $json$"Когда новый компьютер скачивал историю, каждый старый ответ сразу превращался в уведомление. Теперь уведомляют только запросы, сделанные на этом компьютере; то, что приходит с другого компьютера через синхронизацию, — нет."$json$::jsonb),
  ('ja', 'whatsNew.item.syncedHistoryQuiet.detail', $json$"新しいコンピューターが履歴をダウンロードすると、過去の回答がすべて一度に通知になっていました。今後は、このコンピューターで行った依頼だけが通知され、同期で別のコンピューターから届いたものは通知されません。"$json$::jsonb),
  ('de', 'whatsNew.item.syncedHistoryQuiet.detail', $json$"Wenn ein neuer Computer den Verlauf herunterlud, wurde jede frühere Antwort auf einmal zu einer Benachrichtigung. Jetzt benachrichtigen nur Anfragen, die auf diesem Computer gestellt wurden; was über die Synchronisierung von einem anderen Computer kommt, nicht."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.answerNoBlank.title', $json$"Uma resposta não deixa mais a janela em branco"$json$::jsonb),
  ('en', 'whatsNew.item.answerNoBlank.title', $json$"An answer no longer blanks the window"$json$::jsonb),
  ('es', 'whatsNew.item.answerNoBlank.title', $json$"Una respuesta ya no deja la ventana en blanco"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.answerNoBlank.title', $json$"回答不再让窗口变成空白"$json$::jsonb),
  ('hi', 'whatsNew.item.answerNoBlank.title', $json$"कोई जवाब अब विंडो को खाली नहीं करता"$json$::jsonb),
  ('ar', 'whatsNew.item.answerNoBlank.title', $json$"لم يعد الرد يترك النافذة فارغة"$json$::jsonb),
  ('fr', 'whatsNew.item.answerNoBlank.title', $json$"Une réponse ne laisse plus la fenêtre vide"$json$::jsonb),
  ('ru', 'whatsNew.item.answerNoBlank.title', $json$"Ответ больше не оставляет окно пустым"$json$::jsonb),
  ('ja', 'whatsNew.item.answerNoBlank.title', $json$"回答でウィンドウが真っ白にならなくなりました"$json$::jsonb),
  ('de', 'whatsNew.item.answerNoBlank.title', $json$"Eine Antwort lässt das Fenster nicht mehr leer"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.answerNoBlank.detail', $json$"Uma resposta com um link cujo endereço tinha um % solto (como docs/100%.md) deixava a janela inteira em branco, toda vez que o chat abria. Agora o link aparece normalmente. E, se uma tela ainda falhar ao desenhar, ela mostra o que deu errado e um botão Tentar de novo, com o resto do app funcionando."$json$::jsonb),
  ('en', 'whatsNew.item.answerNoBlank.detail', $json$"An answer with a link whose address had a loose % sign (like docs/100%.md) left the whole window blank, every time the chat opened. Now the link shows normally. And if a screen still fails to draw, it shows what went wrong and a Try again button, with the rest of the app still working."$json$::jsonb),
  ('es', 'whatsNew.item.answerNoBlank.detail', $json$"Una respuesta con un enlace cuya dirección tenía un % suelto (como docs/100%.md) dejaba toda la ventana en blanco, cada vez que se abría el chat. Ahora el enlace se muestra con normalidad. Y si una pantalla aún falla al dibujarse, muestra qué salió mal y un botón Intentar de nuevo, con el resto de la app funcionando."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.answerNoBlank.detail', $json$"如果回答中有一个链接，其地址带有单独的 %（例如 docs/100%.md），整个窗口就会变成空白，而且每次打开该聊天都会如此。现在链接会正常显示。即使某个页面仍然无法绘制，它也会显示出错原因和“重试”按钮，应用的其他部分照常运行。"$json$::jsonb),
  ('hi', 'whatsNew.item.answerNoBlank.detail', $json$"अगर किसी जवाब में ऐसा लिंक होता जिसके पते में अकेला % था (जैसे docs/100%.md), तो पूरी विंडो खाली हो जाती थी, हर बार जब चैट खुलती। अब लिंक सामान्य रूप से दिखता है। और अगर कोई स्क्रीन फिर भी बन न पाए, तो वह दिखाती है कि क्या गलत हुआ और एक फिर से कोशिश करें बटन, जबकि बाकी ऐप चलता रहता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.answerNoBlank.detail', $json$"كان الرد الذي يحتوي على رابط في عنوانه علامة % منفردة (مثل docs/100%.md) يترك النافذة كلها فارغة، في كل مرة تُفتح فيها المحادثة. الآن يظهر الرابط بشكل طبيعي. وإذا فشلت شاشة في الرسم رغم ذلك، فإنها تعرض ما حدث وزر «حاول مرة أخرى»، بينما يواصل بقية التطبيق العمل."$json$::jsonb),
  ('fr', 'whatsNew.item.answerNoBlank.detail', $json$"Une réponse contenant un lien dont l’adresse avait un % isolé (comme docs/100%.md) laissait toute la fenêtre vide, à chaque ouverture du chat. Désormais, le lien s’affiche normalement. Et si un écran n’arrive toujours pas à s’afficher, il indique ce qui s’est passé avec un bouton Réessayer, et le reste de l’app continue de fonctionner."$json$::jsonb),
  ('ru', 'whatsNew.item.answerNoBlank.detail', $json$"Ответ со ссылкой, в адресе которой был одиночный знак % (например, docs/100%.md), оставлял всё окно пустым — каждый раз при открытии чата. Теперь ссылка отображается как обычно. А если экран всё же не удаётся отрисовать, он показывает, что пошло не так, и кнопку «Попробовать снова», а остальное приложение продолжает работать."$json$::jsonb),
  ('ja', 'whatsNew.item.answerNoBlank.detail', $json$"アドレスに単独の %（docs/100%.md など）を含むリンクがある回答で、チャットを開くたびにウィンドウ全体が真っ白になっていました。今後はリンクが通常どおり表示されます。それでも画面の描画に失敗した場合は、何が起きたかと「もう一度試す」ボタンが表示され、アプリのほかの部分はそのまま動きます。"$json$::jsonb),
  ('de', 'whatsNew.item.answerNoBlank.detail', $json$"Eine Antwort mit einem Link, dessen Adresse ein einzelnes %-Zeichen enthielt (etwa docs/100%.md), ließ das ganze Fenster leer, jedes Mal, wenn der Chat geöffnet wurde. Jetzt wird der Link normal angezeigt. Und wenn ein Bildschirm trotzdem nicht gezeichnet werden kann, zeigt er, was schiefgelaufen ist, und eine Schaltfläche Erneut versuchen, während der Rest der App weiterläuft."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.orgChatClones.title', $json$"O chat geral conta todo clone da pasta"$json$::jsonb),
  ('en', 'whatsNew.item.orgChatClones.title', $json$"General chat counts every clone in the folder"$json$::jsonb),
  ('es', 'whatsNew.item.orgChatClones.title', $json$"El chat general cuenta cada clon de la carpeta"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.orgChatClones.title', $json$"通用聊天会计入文件夹中的每个克隆"$json$::jsonb),
  ('hi', 'whatsNew.item.orgChatClones.title', $json$"सामान्य चैट फ़ोल्डर के हर क्लोन को गिनती है"$json$::jsonb),
  ('ar', 'whatsNew.item.orgChatClones.title', $json$"المحادثة العامة تحتسب كل نسخة في المجلد"$json$::jsonb),
  ('fr', 'whatsNew.item.orgChatClones.title', $json$"Le chat général compte chaque clone du dossier"$json$::jsonb),
  ('ru', 'whatsNew.item.orgChatClones.title', $json$"Общий чат учитывает каждый клон в папке"$json$::jsonb),
  ('ja', 'whatsNew.item.orgChatClones.title', $json$"総合チャットがフォルダー内のすべてのクローンを数えるように"$json$::jsonb),
  ('de', 'whatsNew.item.orgChatClones.title', $json$"Der allgemeine Chat zählt jeden Klon im Ordner"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.orgChatClones.detail', $json$"Antes do primeiro chat geral, a janela que lista o que o chat enxerga contava só os repositórios que são projeto neste computador: um clonado na pasta pelo terminal aparecia como \"não está neste computador\". Agora conta todo clone achado dentro da pasta da organização."$json$::jsonb),
  ('en', 'whatsNew.item.orgChatClones.detail', $json$"Before the first general chat, the window that lists what the chat sees counted only the repositories that are projects on this computer: one cloned in the folder by the terminal showed as \"not on this computer\". Now every clone found inside the organization folder counts."$json$::jsonb),
  ('es', 'whatsNew.item.orgChatClones.detail', $json$"Antes del primer chat general, la ventana que muestra lo que ve el chat contaba solo los repositorios que son proyectos en este equipo: uno clonado en la carpeta desde la terminal aparecía como \"no está en este equipo\". Ahora cuenta cada clon encontrado dentro de la carpeta de la organización."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.orgChatClones.detail', $json$"在第一个通用聊天之前，列出聊天可见内容的窗口只计算在这台计算机上是项目的仓库：通过终端克隆到文件夹中的仓库会显示为“不在此计算机上”。现在，在组织文件夹内找到的每个克隆都会计入。"$json$::jsonb),
  ('hi', 'whatsNew.item.orgChatClones.detail', $json$"पहली सामान्य चैट से पहले, जो विंडो बताती है कि चैट क्या देखती है, वह सिर्फ़ उन रिपॉज़िटरी को गिनती थी जो इस कंप्यूटर पर प्रोजेक्ट हैं: टर्मिनल से फ़ोल्डर में क्लोन की गई रिपॉज़िटरी \"इस कंप्यूटर पर नहीं है\" दिखती थी। अब संगठन के फ़ोल्डर के अंदर मिला हर क्लोन गिना जाता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.orgChatClones.detail', $json$"قبل أول محادثة عامة، كانت النافذة التي تعرض ما تراه المحادثة تحتسب فقط المستودعات التي هي مشاريع على هذا الحاسوب: المستودع المستنسخ في المجلد من الطرفية كان يظهر على أنه «غير موجود على هذا الحاسوب». الآن تُحتسب كل نسخة يُعثر عليها داخل مجلد المؤسسة."$json$::jsonb),
  ('fr', 'whatsNew.item.orgChatClones.detail', $json$"Avant le premier chat général, la fenêtre qui liste ce que voit le chat ne comptait que les dépôts qui sont des projets sur cet ordinateur : un dépôt cloné dans le dossier depuis le terminal apparaissait comme « absent de cet ordinateur ». Désormais, chaque clone trouvé dans le dossier de l’organisation compte."$json$::jsonb),
  ('ru', 'whatsNew.item.orgChatClones.detail', $json$"Перед первым общим чатом окно со списком того, что видит чат, учитывало только репозитории, которые являются проектами на этом компьютере: клонированный в папку через терминал показывался как «нет на этом компьютере». Теперь учитывается каждый клон, найденный внутри папки организации."$json$::jsonb),
  ('ja', 'whatsNew.item.orgChatClones.detail', $json$"最初の総合チャットの前に、チャットから見えるものを一覧するウィンドウは、このコンピューターでプロジェクトになっているリポジトリだけを数えていました。ターミナルでフォルダーにクローンしたものは「このコンピューターにない」と表示されていました。今後は、組織フォルダー内で見つかったクローンはすべて含まれます。"$json$::jsonb),
  ('de', 'whatsNew.item.orgChatClones.detail', $json$"Vor dem ersten allgemeinen Chat zählte das Fenster, das zeigt, was der Chat sieht, nur die Repositorys, die auf diesem Computer Projekte sind: Ein im Terminal in den Ordner geklontes Repository erschien als „nicht auf diesem Computer“. Jetzt zählt jeder Klon, der im Ordner der Organisation gefunden wird."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.modsKeepRemote.title', $json$"Salvar os mods mantém o que mudou em outro lugar"$json$::jsonb),
  ('en', 'whatsNew.item.modsKeepRemote.title', $json$"Saving mods keeps what changed elsewhere"$json$::jsonb),
  ('es', 'whatsNew.item.modsKeepRemote.title', $json$"Guardar los mods mantiene lo que cambió en otro lugar"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.modsKeepRemote.title', $json$"保存模组时保留在其他地方所做的更改"$json$::jsonb),
  ('hi', 'whatsNew.item.modsKeepRemote.title', $json$"मॉड सहेजने पर कहीं और हुए बदलाव बने रहते हैं"$json$::jsonb),
  ('ar', 'whatsNew.item.modsKeepRemote.title', $json$"حفظ الإضافات يحتفظ بما تغيّر في مكان آخر"$json$::jsonb),
  ('fr', 'whatsNew.item.modsKeepRemote.title', $json$"Enregistrer les mods garde ce qui a changé ailleurs"$json$::jsonb),
  ('ru', 'whatsNew.item.modsKeepRemote.title', $json$"Сохранение модов сохраняет изменения, сделанные в другом месте"$json$::jsonb),
  ('ja', 'whatsNew.item.modsKeepRemote.title', $json$"Mod の保存で、ほかの場所での変更が保たれるように"$json$::jsonb),
  ('de', 'whatsNew.item.modsKeepRemote.title', $json$"Das Speichern der Mods behält, was sich anderswo geändert hat"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.modsKeepRemote.detail', $json$"Com alterações não salvas em Configuração › Mods, um mod que outro computador ou o site instalou nesse meio-tempo era desinstalado ao salvar. Agora salvar aplica só o que você mudou na aba."$json$::jsonb),
  ('en', 'whatsNew.item.modsKeepRemote.detail', $json$"With unsaved changes in Settings › Mods, a mod that another computer or the site installed in the meantime was uninstalled when you saved. Now saving applies only what you changed in the tab."$json$::jsonb),
  ('es', 'whatsNew.item.modsKeepRemote.detail', $json$"Con cambios sin guardar en Configuración › Mods, un mod que otro equipo o el sitio instaló mientras tanto se desinstalaba al guardar. Ahora al guardar se aplica solo lo que cambiaste en la pestaña."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.modsKeepRemote.detail', $json$"在“设置 › 模组”中有未保存的更改时，另一台计算机或网站在此期间安装的模组会在保存时被卸载。现在保存时只应用你在该标签页中所做的更改。"$json$::jsonb),
  ('hi', 'whatsNew.item.modsKeepRemote.detail', $json$"सेटिंग्स › मॉड में बिना सहेजे बदलाव रहते हुए, अगर इस बीच दूसरे कंप्यूटर या साइट ने कोई मॉड इंस्टॉल किया, तो सहेजने पर वह अनइंस्टॉल हो जाता था। अब सहेजने पर सिर्फ़ वही लागू होता है जो आपने टैब में बदला।"$json$::jsonb),
  ('ar', 'whatsNew.item.modsKeepRemote.detail', $json$"مع وجود تغييرات غير محفوظة في الإعدادات › الإضافات، كانت الإضافة التي ثبّتها حاسوب آخر أو الموقع في هذه الأثناء تُلغى عند الحفظ. الآن يطبّق الحفظ فقط ما غيّرته في التبويب."$json$::jsonb),
  ('fr', 'whatsNew.item.modsKeepRemote.detail', $json$"Avec des changements non enregistrés dans Configuration › Mods, un mod installé entre-temps par un autre ordinateur ou par le site était désinstallé à l’enregistrement. Désormais, l’enregistrement n’applique que ce que vous avez changé dans l’onglet."$json$::jsonb),
  ('ru', 'whatsNew.item.modsKeepRemote.detail', $json$"При несохранённых изменениях в Настройки › Моды мод, который тем временем установил другой компьютер или сайт, удалялся при сохранении. Теперь при сохранении применяется только то, что вы изменили на вкладке."$json$::jsonb),
  ('ja', 'whatsNew.item.modsKeepRemote.detail', $json$"設定 › Mod に未保存の変更があるとき、その間に別のコンピューターやサイトがインストールした Mod が、保存時にアンインストールされていました。今後は、保存時にタブで変更した内容だけが適用されます。"$json$::jsonb),
  ('de', 'whatsNew.item.modsKeepRemote.detail', $json$"Mit ungespeicherten Änderungen unter Einstellungen › Mods wurde ein Mod, den ein anderer Computer oder die Website inzwischen installiert hatte, beim Speichern deinstalliert. Jetzt übernimmt das Speichern nur, was Sie im Tab geändert haben."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.mcpDraftNoWait.title', $json$"O /mcp não espera mais o pedido que está rodando"$json$::jsonb),
  ('en', 'whatsNew.item.mcpDraftNoWait.title', $json$"/mcp no longer waits for the running request"$json$::jsonb),
  ('es', 'whatsNew.item.mcpDraftNoWait.title', $json$"/mcp ya no espera la solicitud en curso"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.mcpDraftNoWait.title', $json$"/mcp 不再等待正在运行的请求"$json$::jsonb),
  ('hi', 'whatsNew.item.mcpDraftNoWait.title', $json$"/mcp अब चल रहे अनुरोध का इंतज़ार नहीं करता"$json$::jsonb),
  ('ar', 'whatsNew.item.mcpDraftNoWait.title', $json$"لم يعد /mcp ينتظر الطلب الجاري"$json$::jsonb),
  ('fr', 'whatsNew.item.mcpDraftNoWait.title', $json$"/mcp n’attend plus la demande en cours"$json$::jsonb),
  ('ru', 'whatsNew.item.mcpDraftNoWait.title', $json$"/mcp больше не ждёт выполняющийся запрос"$json$::jsonb),
  ('ja', 'whatsNew.item.mcpDraftNoWait.title', $json$"/mcp が実行中の依頼を待たなくなりました"$json$::jsonb),
  ('de', 'whatsNew.item.mcpDraftNoWait.title', $json$"/mcp wartet nicht mehr auf die laufende Anfrage"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.mcpDraftNoWait.detail', $json$"Montar um servidor MCP com o /mcp esperava o pedido que rodava em outro chat terminar, às vezes por minutos. Agora o rascunho vem na hora."$json$::jsonb),
  ('en', 'whatsNew.item.mcpDraftNoWait.detail', $json$"Drafting an MCP server with /mcp waited for the request running in another chat to finish, minutes sometimes. Now the draft comes right away."$json$::jsonb),
  ('es', 'whatsNew.item.mcpDraftNoWait.detail', $json$"Preparar un servidor MCP con /mcp esperaba a que terminara la solicitud que se ejecutaba en otro chat, a veces durante minutos. Ahora el borrador llega de inmediato."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.mcpDraftNoWait.detail', $json$"用 /mcp 生成 MCP 服务器时，要等另一个聊天中正在运行的请求结束，有时要等好几分钟。现在草稿会立即生成。"$json$::jsonb),
  ('hi', 'whatsNew.item.mcpDraftNoWait.detail', $json$"/mcp से MCP सर्वर बनाते समय दूसरी चैट में चल रहे अनुरोध के खत्म होने का इंतज़ार होता था, कभी-कभी कई मिनट। अब ड्राफ़्ट तुरंत आता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.mcpDraftNoWait.detail', $json$"كان إعداد خادم MCP عبر /mcp ينتظر انتهاء الطلب الجاري في محادثة أخرى، لدقائق أحيانًا. الآن تصل المسودة فورًا."$json$::jsonb),
  ('fr', 'whatsNew.item.mcpDraftNoWait.detail', $json$"Préparer un serveur MCP avec /mcp attendait la fin de la demande en cours dans un autre chat, parfois pendant des minutes. Désormais, le brouillon arrive tout de suite."$json$::jsonb),
  ('ru', 'whatsNew.item.mcpDraftNoWait.detail', $json$"Подготовка MCP-сервера через /mcp ждала, пока завершится запрос в другом чате, иногда по нескольку минут. Теперь черновик появляется сразу."$json$::jsonb),
  ('ja', 'whatsNew.item.mcpDraftNoWait.detail', $json$"/mcp で MCP サーバーを作るとき、別のチャットで実行中の依頼が終わるまで、ときには数分待たされていました。今後は下書きがすぐに届きます。"$json$::jsonb),
  ('de', 'whatsNew.item.mcpDraftNoWait.detail', $json$"Das Erstellen eines MCP-Servers mit /mcp wartete, bis die Anfrage in einem anderen Chat fertig war, manchmal minutenlang. Jetzt kommt der Entwurf sofort."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.editorNoFreeze.title', $json$"Seguir o agente no editor não trava a janela"$json$::jsonb),
  ('en', 'whatsNew.item.editorNoFreeze.title', $json$"Following the agent in the editor does not freeze the window"$json$::jsonb),
  ('es', 'whatsNew.item.editorNoFreeze.title', $json$"Seguir al agente en el editor no congela la ventana"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.editorNoFreeze.title', $json$"在编辑器中跟随代理不会卡住窗口"$json$::jsonb),
  ('hi', 'whatsNew.item.editorNoFreeze.title', $json$"एडिटर में एजेंट को फ़ॉलो करने से विंडो नहीं अटकती"$json$::jsonb),
  ('ar', 'whatsNew.item.editorNoFreeze.title', $json$"متابعة الوكيل في المحرر لا تجمّد النافذة"$json$::jsonb),
  ('fr', 'whatsNew.item.editorNoFreeze.title', $json$"Suivre l’agent dans l’éditeur ne fige plus la fenêtre"$json$::jsonb),
  ('ru', 'whatsNew.item.editorNoFreeze.title', $json$"Следование за агентом в редакторе не замораживает окно"$json$::jsonb),
  ('ja', 'whatsNew.item.editorNoFreeze.title', $json$"エディターでエージェントを追ってもウィンドウが固まらないように"$json$::jsonb),
  ('de', 'whatsNew.item.editorNoFreeze.title', $json$"Dem Agenten im Editor zu folgen friert das Fenster nicht ein"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.editorNoFreeze.detail', $json$"Abrir no VS Code ou no Cursor, pelo painel Código, um arquivo que mudou podia travar a janela por um instante enquanto o git lia a pasta. Agora ele abre sem segurar a janela."$json$::jsonb),
  ('en', 'whatsNew.item.editorNoFreeze.detail', $json$"Opening a changed file in VS Code or Cursor from the Code panel could freeze the window for a moment while git read the folder. Now it opens without holding the window."$json$::jsonb),
  ('es', 'whatsNew.item.editorNoFreeze.detail', $json$"Abrir en VS Code o Cursor, desde el panel Código, un archivo que cambió podía congelar la ventana un momento mientras git leía la carpeta. Ahora se abre sin bloquear la ventana."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.editorNoFreeze.detail', $json$"从“代码”面板在 VS Code 或 Cursor 中打开已更改的文件时，窗口可能会在 git 读取文件夹期间卡住片刻。现在打开文件不会占住窗口。"$json$::jsonb),
  ('hi', 'whatsNew.item.editorNoFreeze.detail', $json$"कोड पैनल से VS Code या Cursor में बदली हुई फ़ाइल खोलने पर, git के फ़ोल्डर पढ़ते समय विंडो पल भर के लिए अटक सकती थी। अब फ़ाइल विंडो को रोके बिना खुलती है।"$json$::jsonb),
  ('ar', 'whatsNew.item.editorNoFreeze.detail', $json$"كان فتح ملف تغيّر في VS Code أو Cursor من لوحة «الشيفرة» قد يجمّد النافذة لحظةً بينما يقرأ git المجلد. الآن يُفتح دون تعطيل النافذة."$json$::jsonb),
  ('fr', 'whatsNew.item.editorNoFreeze.detail', $json$"Ouvrir dans VS Code ou Cursor, depuis le panneau Code, un fichier modifié pouvait figer la fenêtre un instant pendant que git lisait le dossier. Désormais, il s’ouvre sans bloquer la fenêtre."$json$::jsonb),
  ('ru', 'whatsNew.item.editorNoFreeze.detail', $json$"Открытие изменённого файла в VS Code или Cursor из панели «Код» могло на мгновение заморозить окно, пока git читал папку. Теперь файл открывается, не задерживая окно."$json$::jsonb),
  ('ja', 'whatsNew.item.editorNoFreeze.detail', $json$"「コード」パネルから変更されたファイルを VS Code や Cursor で開くと、git がフォルダーを読む間、ウィンドウが一瞬固まることがありました。今後はウィンドウを止めずに開きます。"$json$::jsonb),
  ('de', 'whatsNew.item.editorNoFreeze.detail', $json$"Eine geänderte Datei aus dem Code-Panel in VS Code oder Cursor zu öffnen, konnte das Fenster kurz einfrieren, während git den Ordner las. Jetzt öffnet sie sich, ohne das Fenster aufzuhalten."$json$::jsonb),
  ('pt-BR', 'docs.notifications.usage', $json$"No app, o sino fica à direita do logotipo na lateral; no Ctrl+K, escolha Notificações para abri-lo. No site, ele fica na barra de cima assim que você entra. Clique numa notificação para ir à organização; o convite pode ser aceito ou recusado ali mesmo, na lista. Marque todas como lidas ou limpe as lidas pelo painel. O site atualiza a lista a cada minuto e quando você a abre. Respostas, perguntas e limites só existem no app, no aparelho em que aconteceram. Pedidos que chegam de outro computador pela sincronização, e o histórico que um computador novo baixa, não viram notificação."$json$::jsonb),
  ('en', 'docs.notifications.usage', $json$"In the app the bell sits to the right of the logo in the sidebar; in Ctrl+K choose Notifications to open it. On the site it sits in the top bar once you are signed in. Click a notification to go to its organization; an invitation can be accepted or declined right in the list. Mark all as read, or clear the read ones, from the panel. The site refreshes the list every minute and when you open it. Answers, questions and limits only exist in the app, on the device where they happened. Requests that arrive from another computer through sync, and the history a new computer downloads, do not become notifications."$json$::jsonb),
  ('es', 'docs.notifications.usage', $json$"En la app, la campana está a la derecha del logotipo en la barra lateral; en Ctrl+K elige Notificaciones para abrirla. En el sitio está en la barra superior en cuanto inicias sesión. Haz clic en una notificación para ir a su organización; la invitación se puede aceptar o rechazar ahí mismo, en la lista. Marca todas como leídas o limpia las leídas desde el panel. El sitio actualiza la lista cada minuto y al abrirla. Las respuestas, preguntas y límites solo existen en la app, en el dispositivo donde ocurrieron. Las solicitudes que llegan de otro equipo por la sincronización, y el historial que descarga un equipo nuevo, no se convierten en notificaciones."$json$::jsonb),
  ('zh-CN', 'docs.notifications.usage', $json$"在应用中，铃铛位于侧边栏 logo 右侧；在 Ctrl+K 中选择“通知”即可打开。在网站上，登录后它位于顶部栏。点击通知可前往对应的组织；邀请可直接在列表中接受或拒绝。可在面板中将全部标为已读或清除已读通知。网站每分钟以及打开列表时都会刷新。回答、提问和额度提醒只存在于应用中，只在发生它们的设备上。通过同步从另一台计算机传来的请求，以及新计算机下载的历史记录，都不会变成通知。"$json$::jsonb),
  ('hi', 'docs.notifications.usage', $json$"ऐप में घंटी साइडबार में लोगो के दाईं ओर है; Ctrl+K में सूचनाएँ चुनकर उसे खोलें। साइट पर साइन इन करते ही वह ऊपर की पट्टी में दिखती है। किसी सूचना पर क्लिक करके उसके संगठन पर जाएँ; आमंत्रण सूची में ही स्वीकार या अस्वीकार किया जा सकता है। पैनल से सभी को पढ़ा हुआ चिह्नित करें या पढ़ी हुई साफ़ करें। साइट सूची को हर मिनट और खोलने पर ताज़ा करती है। उत्तर, सवाल और सीमाएँ केवल ऐप में होती हैं, उसी डिवाइस पर जहाँ वे हुईं। सिंक के ज़रिए दूसरे कंप्यूटर से आने वाले अनुरोध, और नया कंप्यूटर जो इतिहास डाउनलोड करता है, सूचना नहीं बनते।"$json$::jsonb),
  ('ar', 'docs.notifications.usage', $json$"في التطبيق يقع الجرس إلى يمين الشعار في الشريط الجانبي؛ وفي Ctrl+K اختر الإشعارات لفتحه. وفي الموقع يظهر في الشريط العلوي بمجرد تسجيل الدخول. انقر على إشعار للانتقال إلى مؤسسته؛ ويمكن قبول الدعوة أو رفضها من القائمة مباشرة. علّم الكل كمقروء أو امسح المقروء من اللوحة. يحدّث الموقع القائمة كل دقيقة وعند فتحها. الردود والأسئلة والحدود موجودة في التطبيق فقط، على الجهاز الذي حدثت عليه. الطلبات التي تصل من حاسوب آخر عبر المزامنة، والسجل الذي ينزّله حاسوب جديد، لا تتحول إلى إشعارات."$json$::jsonb),
  ('fr', 'docs.notifications.usage', $json$"Dans l'application, la cloche est à droite du logo dans la barre latérale ; dans Ctrl+K, choisissez Notifications pour l'ouvrir. Sur le site, elle se trouve dans la barre du haut dès que vous êtes connecté. Cliquez sur une notification pour aller à son organisation ; une invitation peut être acceptée ou refusée directement dans la liste. Marquez tout comme lu ou effacez les lues depuis le panneau. Le site actualise la liste chaque minute et à son ouverture. Les réponses, questions et limites n'existent que dans l'application, sur l'appareil où elles se sont produites. Les demandes qui arrivent d’un autre ordinateur par la synchronisation, et l’historique qu’un nouvel ordinateur télécharge, ne deviennent pas des notifications."$json$::jsonb),
  ('ru', 'docs.notifications.usage', $json$"В приложении колокольчик находится справа от логотипа в боковой панели; в Ctrl+K выберите «Уведомления», чтобы открыть его. На сайте он находится в верхней панели после входа. Нажмите на уведомление, чтобы перейти к его организации; приглашение можно принять или отклонить прямо в списке. Отметить всё прочитанным или очистить прочитанные можно в панели. Сайт обновляет список каждую минуту и при открытии. Ответы, вопросы и лимиты есть только в приложении, на устройстве, где они произошли. Запросы, которые приходят с другого компьютера через синхронизацию, и история, которую скачивает новый компьютер, не становятся уведомлениями."$json$::jsonb),
  ('ja', 'docs.notifications.usage', $json$"アプリでは、ベルはサイドバーのロゴの右にあります。Ctrl+K で「通知」を選ぶと開きます。サイトでは、サインインするとトップバーに表示されます。通知をクリックするとその組織に移動し、招待はリストの中でそのまま承諾または辞退できます。パネルから、すべて既読にしたり既読を消去したりできます。サイトはリストを 1 分ごと、および開いたときに更新します。回答、質問、上限の通知はアプリだけにあり、発生した端末にのみ表示されます。同期で別のコンピューターから届く依頼や、新しいコンピューターがダウンロードする履歴は、通知になりません。"$json$::jsonb),
  ('de', 'docs.notifications.usage', $json$"In der App sitzt die Glocke rechts neben dem Logo in der Seitenleiste; in Strg+K öffnest du sie mit Benachrichtigungen. Auf der Website sitzt sie in der oberen Leiste, sobald du angemeldet bist. Klicke auf eine Benachrichtigung, um zur Organisation zu gelangen; eine Einladung kannst du direkt in der Liste annehmen oder ablehnen. Alle als gelesen markieren oder gelesene löschen geht im Panel. Die Website aktualisiert die Liste jede Minute und beim Öffnen. Antworten, Fragen und Limits gibt es nur in der App, auf dem Gerät, auf dem sie passiert sind. Anfragen, die über die Synchronisierung von einem anderen Computer kommen, und der Verlauf, den ein neuer Computer herunterlädt, werden nicht zu Benachrichtigungen."$json$::jsonb),
  ('pt-BR', 'docs.environments.usage', $json$"Com pelo menos uma organização, um seletor abaixo do logotipo lista Pessoal e suas organizações; ao escolher uma, a janela recarrega com os dados daquele ambiente. No ambiente de uma organização, o menu lateral mostra só ela: a placa dela no alto e, abaixo, Projetos, Estatísticas, Portaria, Membros, Repositórios, MCP e Skills; Sistema e Planos só aparecem no ambiente Pessoal, e o Ctrl+K, os atalhos e o menu da bandeja seguem o mesmo menu. Ali, Projetos tem a organização no título e o botão Abrir chat dela no lugar de Novo projeto. Um ambiente de organização novo começa com as configurações padrão e sem projetos: ligue o que precisar em Configurações e use Abrir chat em Projetos e Repositórios no menu lateral para abrir o chat geral ou clonar os repositórios dela. No Ctrl+K, escolha \"Trocar para o ambiente\" do que quiser. Os projetos que você já tinha de uma organização foram para o ambiente dela na primeira abertura após atualizar, e uma cópia do banco pessoal antigo fica ao lado dele. Ao trocar, aparece um carregamento até os dados do ambiente chegarem; o app não procura atualização nessa recarga. O que outro computador ou o site grava no ambiente (projetos, chats, respostas, configurações, mods) aparece sozinho depois da próxima sincronização; num computador novo, os projetos aparecem logo depois do login."$json$::jsonb),
  ('en', 'docs.environments.usage', $json$"With at least one organization, a selector under the logo lists Personal and your organizations; choosing one reloads the window with that environment's data. Inside an organization's environment the side menu shows only that organization: its card at the top, then Projects, Statistics, Gatehouse, Members, Repositories, MCP and Skills; System and Plans appear only in the Personal environment, and Ctrl+K, the shortcuts and the tray menu follow the same menu. There, Projects is headed by the organization, with its Open chat button in place of New project. A new organization environment starts with the default settings and no projects: turn on what you need in Settings, and use Open chat on Projects and Repositories in the side menu to open its general chat or clone its repositories. In Ctrl+K, choose \"Switch to environment\" for the one you want. Projects you already had for an organization moved to its environment at the first start after updating, and a copy of the old personal database stays next to it. While switching, a loading screen shows until the environment's data arrives; the app does not look for updates on that reload. What another computer or the site writes in the environment (projects, chats, answers, settings, mods) shows up by itself after the next sync; on a new computer the projects appear soon after signing in."$json$::jsonb),
  ('es', 'docs.environments.usage', $json$"Con al menos una organización, un selector bajo el logotipo lista Personal y tus organizaciones; al elegir una, la ventana se recarga con los datos de ese entorno. En el entorno de una organización, el menú lateral muestra solo esa organización: su tarjeta arriba y, debajo, Proyectos, Estadísticas, Portería, Miembros, Repositorios, MCP y Skills; Sistema y Planes solo aparecen en el entorno Personal, y Ctrl+K, los atajos y el menú de la bandeja siguen el mismo menú. Allí, Proyectos lleva la organización en el título y su botón Abrir chat en lugar de Nuevo proyecto. Un entorno de organización nuevo empieza con los ajustes predeterminados y sin proyectos: activa lo que necesites en Ajustes y usa Abrir chat en Proyectos y Repositorios en el menú lateral para abrir su chat general o clonar sus repositorios. En Ctrl+K elige \"Cambiar al entorno\" del que quieras. Los proyectos que ya tenías de una organización pasaron a su entorno en el primer inicio tras actualizar, y una copia de la base personal anterior queda a su lado. Al cambiar, aparece una pantalla de carga hasta que llegan los datos del entorno; la app no busca actualizaciones en esa recarga. Lo que otro equipo o el sitio escribe en el entorno (proyectos, chats, respuestas, configuración, mods) aparece solo después de la siguiente sincronización; en un equipo nuevo, los proyectos aparecen poco después de iniciar sesión."$json$::jsonb),
  ('zh-CN', 'docs.environments.usage', $json$"只要有至少一个组织，logo 下方的选择器就会列出“个人”和你的组织；选择其一会用该环境的数据重新加载窗口。在组织的环境中，侧边菜单只显示该组织：顶部是它的卡片，下面是项目、统计、门岗、成员、仓库、MCP 和 Skills；系统和套餐只出现在“个人”环境中，Ctrl+K、快捷键和托盘菜单也遵循同样的菜单。在那里，“项目”页面的标题是该组织，“新建项目”的位置换成了它的“打开聊天”按钮。新的组织环境以默认设置且没有项目开始：在设置中打开所需内容，并通过“项目”中的“打开聊天”和侧边菜单中的“仓库”打开其通用聊天或克隆其仓库。在 Ctrl+K 中选择“切换到环境”即可切换。你之前属于某个组织的项目，会在更新后首次启动时移到该组织的环境，旧的个人数据库副本保留在旁边。切换时会显示加载界面，直到该环境的数据到达；这次重新加载不会检查更新。另一台计算机或网站在该环境中写入的内容（项目、聊天、回答、设置、模组）会在下一次同步后自动显示；在新计算机上，登录后不久就会显示项目。"$json$::jsonb),
  ('hi', 'docs.environments.usage', $json$"कम से कम एक संगठन होने पर लोगो के नीचे का चयनकर्ता व्यक्तिगत और आपके संगठनों को सूचीबद्ध करता है; एक चुनने पर विंडो उस परिवेश के डेटा के साथ फिर से लोड होती है। किसी संगठन के परिवेश में साइड मेनू केवल उसी संगठन को दिखाता है: ऊपर उसका कार्ड, फिर प्रोजेक्ट, आँकड़े, गेट, सदस्य, रिपॉज़िटरी, MCP और Skills; सिस्टम और प्लान केवल व्यक्तिगत परिवेश में दिखते हैं, और Ctrl+K, शॉर्टकट और ट्रे मेनू भी इसी मेनू का पालन करते हैं। वहाँ प्रोजेक्ट के शीर्षक में संगठन होता है और नया प्रोजेक्ट की जगह उसका चैट खोलें बटन। नया संगठन परिवेश डिफ़ॉल्ट सेटिंग और बिना प्रोजेक्ट के शुरू होता है: सेटिंग में जो चाहिए चालू करें और प्रोजेक्ट में चैट खोलें तथा साइड मेनू के रिपॉज़िटरी से उसकी सामान्य चैट खोलें या उसकी रिपॉज़िटरी क्लोन करें। Ctrl+K में मनचाहे परिवेश के लिए \"परिवेश पर जाएँ\" चुनें। किसी संगठन के जो प्रोजेक्ट आपके पास पहले से थे, वे अपडेट के बाद पहली शुरुआत पर उसके परिवेश में चले गए, और पुराने व्यक्तिगत डेटाबेस की एक प्रति उसके बगल में रहती है। बदलते समय परिवेश का डेटा आने तक लोडिंग स्क्रीन दिखती है; इस रीलोड में ऐप अपडेट नहीं खोजता। दूसरा कंप्यूटर या साइट इस परिवेश में जो लिखता है (प्रोजेक्ट, चैट, जवाब, सेटिंग्स, मॉड), वह अगले सिंक के बाद अपने-आप दिखता है; नए कंप्यूटर पर साइन इन करने के कुछ ही देर बाद प्रोजेक्ट दिखने लगते हैं।"$json$::jsonb),
  ('ar', 'docs.environments.usage', $json$"عند وجود مؤسسة واحدة على الأقل، تعرض أداة الاختيار تحت الشعار «شخصي» ومؤسساتك؛ واختيار إحداها يعيد تحميل النافذة ببيانات تلك البيئة. في بيئة مؤسسة، تعرض القائمة الجانبية تلك المؤسسة فقط: بطاقتها في الأعلى، ثم المشاريع والإحصاءات والبوابة والأعضاء والمستودعات وMCP وSkills؛ أما النظام والخطط فيظهران في البيئة الشخصية فقط، وتتبع Ctrl+K والاختصارات وقائمة شريط النظام القائمة نفسها. وهناك تحمل صفحة المشاريع اسم المؤسسة عنوانًا، ويحل زر فتح المحادثة الخاص بها محل مشروع جديد. تبدأ بيئة المؤسسة الجديدة بالإعدادات الافتراضية وبلا مشاريع: فعّل ما تحتاجه في الإعدادات واستخدم فتح المحادثة في المشاريع والمستودعات في القائمة الجانبية لفتح محادثتها العامة أو نسخ مستودعاتها. في Ctrl+K اختر «التبديل إلى البيئة» التي تريدها. المشاريع التي كانت لديك لمؤسسة انتقلت إلى بيئتها عند أول تشغيل بعد التحديث، وتبقى نسخة من قاعدة البيانات الشخصية القديمة بجانبها. أثناء التبديل تظهر شاشة تحميل حتى تصل بيانات البيئة؛ ولا يبحث التطبيق عن تحديثات في إعادة التحميل هذه. ما يكتبه حاسوب آخر أو الموقع في البيئة (المشاريع والمحادثات والردود والإعدادات والإضافات) يظهر تلقائيًا بعد المزامنة التالية؛ وعلى حاسوب جديد تظهر المشاريع بعد تسجيل الدخول بقليل."$json$::jsonb),
  ('fr', 'docs.environments.usage', $json$"Avec au moins une organisation, un sélecteur sous le logo liste Personnel et vos organisations ; en choisir une recharge la fenêtre avec les données de cet environnement. Dans l'environnement d'une organisation, le menu latéral ne montre que cette organisation : sa carte en haut puis Projets, Statistiques, Loge, Membres, Dépôts, MCP et Skills ; Système et Forfaits n'apparaissent que dans l'environnement Personnel, et Ctrl+K, les raccourcis et le menu de la zone de notification suivent le même menu. Là, Projets porte l'organisation en titre et son bouton Ouvrir le chat à la place de Nouveau projet. Un nouvel environnement d'organisation démarre avec les réglages par défaut et sans projet : activez ce qu'il vous faut dans Réglages et utilisez Ouvrir le chat dans Projets et Dépôts dans le menu latéral pour ouvrir son chat général ou cloner ses dépôts. Dans Ctrl+K, choisissez « Basculer vers l'environnement » voulu. Les projets que vous aviez déjà pour une organisation sont passés dans son environnement au premier démarrage après la mise à jour, et une copie de l'ancienne base personnelle reste à côté. Pendant le changement, un écran de chargement s'affiche jusqu'à l'arrivée des données de l'environnement ; l'application ne cherche pas de mise à jour lors de ce rechargement. Ce qu’un autre ordinateur ou le site écrit dans l’environnement (projets, chats, réponses, configuration, mods) apparaît tout seul après la synchronisation suivante ; sur un nouvel ordinateur, les projets apparaissent peu après la connexion."$json$::jsonb),
  ('ru', 'docs.environments.usage', $json$"Если есть хотя бы одна организация, переключатель под логотипом перечисляет «Личное» и ваши организации; выбор перезагружает окно с данными этой среды. В среде организации боковое меню показывает только её: карточку наверху, а под ней Проекты, Статистика, Проходная, Участники, Репозитории, MCP и Skills; Система и Тарифы есть только в среде «Личное», а Ctrl+K, сочетания клавиш и меню в трее следуют тому же меню. Там в заголовке «Проектов» стоит организация, а её кнопка «Открыть чат» — на месте «Нового проекта». Новая среда организации начинается с настроек по умолчанию и без проектов: включите нужное в Настройках, а кнопкой «Открыть чат» в «Проектах» и разделом «Репозитории» в боковом меню откройте её общий чат или клонируйте репозитории. В Ctrl+K выберите «Переключиться на среду» нужной. Проекты, которые у вас уже были для организации, при первом запуске после обновления перешли в её среду, а копия прежней личной базы остаётся рядом. Во время переключения показывается экран загрузки, пока не придут данные среды; при этой перезагрузке приложение не ищет обновления. То, что другой компьютер или сайт записывает в среду (проекты, чаты, ответы, настройки, моды), появляется само после следующей синхронизации; на новом компьютере проекты появляются вскоре после входа."$json$::jsonb),
  ('ja', 'docs.environments.usage', $json$"組織が 1 つ以上あると、ロゴの下のセレクターに「個人」と組織が並び、選ぶとその環境のデータでウィンドウが再読み込みされます。組織の環境では、サイドメニューにはその組織だけが表示されます。上部に組織のカード、その下にプロジェクト、統計、ゲート、メンバー、リポジトリ、MCP、Skills が並び、システムとプランは「個人」環境にだけ表示されます。Ctrl+K、ショートカット、トレイメニューも同じメニューに従います。そこでは「プロジェクト」の見出しが組織になり、「新しいプロジェクト」の代わりに組織の「チャットを開く」ボタンが置かれます。新しい組織の環境は既定の設定でプロジェクトなしから始まります。設定で必要なものをオンにし、「プロジェクト」の「チャットを開く」とサイドメニューの「リポジトリ」から全体チャットを開くかリポジトリをクローンしてください。Ctrl+K で「環境に切り替え」を選ぶと目的の環境に移れます。以前から組織に属していたプロジェクトは、更新後の初回起動でその組織の環境に移り、以前の個人データベースのコピーは隣に残ります。切り替え中はその環境のデータが届くまで読み込み画面が表示され、この再読み込みでは更新の確認は行われません。別のコンピューターやサイトがこの環境に書き込んだもの（プロジェクト、チャット、回答、設定、Mod）は、次の同期のあと自動で表示されます。新しいコンピューターでは、サインインしてすぐにプロジェクトが表示されます。"$json$::jsonb),
  ('de', 'docs.environments.usage', $json$"Mit mindestens einer Organisation listet ein Umschalter unter dem Logo Persönlich und deine Organisationen; die Auswahl lädt das Fenster mit den Daten dieser Umgebung neu. In der Umgebung einer Organisation zeigt das Seitenmenü nur diese Organisation: oben ihre Karte, darunter Projekte, Statistiken, Pforte, Mitglieder, Repositories, MCP und Skills; System und Pläne erscheinen nur in der Umgebung Persönlich, und Strg+K, die Tastenkürzel und das Tray-Menü folgen demselben Menü. Dort trägt Projekte die Organisation im Titel und ihren Button Chat öffnen anstelle von Neues Projekt. Eine neue Organisationsumgebung startet mit den Standardeinstellungen und ohne Projekte: Schalte in den Einstellungen ein, was du brauchst, und öffne mit Chat öffnen unter Projekte ihren allgemeinen Chat oder klone ihre Repositories unter Repositories im Seitenmenü. Wähle in Strg+K „Zur Umgebung wechseln“ für die gewünschte. Projekte, die du schon für eine Organisation hattest, sind beim ersten Start nach dem Update in deren Umgebung gewandert, und eine Kopie der alten persönlichen Datenbank bleibt daneben. Beim Wechsel erscheint ein Ladebildschirm, bis die Daten der Umgebung da sind; bei diesem Neuladen sucht die App nicht nach Updates. Was ein anderer Computer oder die Website in die Umgebung schreibt (Projekte, Chats, Antworten, Einstellungen, Mods), erscheint nach der nächsten Synchronisierung von selbst; auf einem neuen Computer erscheinen die Projekte kurz nach der Anmeldung."$json$::jsonb),
  ('pt-BR', 'docs.orgChat.usage', $json$"No ambiente da organização, clique em Chats no menu lateral para abrir ou fechar a lista dos chats gerais, do mais recente para o mais antigo: clique num para continuá-lo ou no + para começar outro. O botão Abrir chat no alto de Projetos também deixa escolher ou começar um. Sem uma pasta da organização neste computador, o JayV pede uma primeiro. Num chat geral, a aba Repositórios do painel Código mostra o git status de cada repositório da pasta e de onde vem a política de LLM dele; os repositórios da organização que não estão na pasta aparecem no fim. Também na paleta de comandos (Ctrl+K): Chats gerais. Antes do primeiro chat geral, uma janela lista quais repositórios da organização o chat enxerga: conta todo clone achado dentro da pasta, mesmo o que não é projeto neste computador."$json$::jsonb),
  ('en', 'docs.orgChat.usage', $json$"In the organization's environment, click Chats in the side menu to open or close the list of general chats, newest first: click one to continue it or + to start another. The Open chat button at the top of Projects also lets you choose or start one. Without an organization folder on this computer, JayV asks for one first. In a general chat, the Repositories tab of the Code panel shows the git status of each repository of the folder and where its LLM policy comes from; the organization's repositories that are not in the folder show at the end. Also in the command palette (Ctrl+K): General chats. Before the first general chat, a window lists which repositories of the organization the chat sees: every clone found inside the folder counts, even one that is not a project on this computer."$json$::jsonb),
  ('es', 'docs.orgChat.usage', $json$"En el entorno de la organización, haz clic en Chats en el menú lateral para abrir o cerrar la lista de chats generales, del más reciente al más antiguo: haz clic en uno para continuarlo o en + para empezar otro. El botón Abrir chat arriba de Proyectos también permite elegir o empezar uno. Sin una carpeta de la organización en este equipo, JayV pide una primero. En un chat general, la pestaña Repositorios del panel Código muestra el git status de cada repositorio de la carpeta y de dónde viene su política de LLM; los repositorios de la organización que no están en la carpeta aparecen al final. También en la paleta de comandos (Ctrl+K): Chats generales. Antes del primer chat general, una ventana muestra qué repositorios de la organización ve el chat: cuenta cada clon encontrado dentro de la carpeta, aunque no sea un proyecto en este equipo."$json$::jsonb),
  ('zh-CN', 'docs.orgChat.usage', $json$"在组织的环境中，点击侧边菜单中的“对话”可展开或收起通用聊天列表，最新的在前：点击其中一个继续，或点 + 开始新的。“项目”顶部的“打开聊天”按钮也可以选择或开始一个。如果本机没有该组织的文件夹，JayV 会先请你指定一个。在通用聊天中，“代码”面板的“仓库”标签页会显示文件夹中每个仓库的 git 状态及其 LLM 策略的来源；不在文件夹中的组织仓库显示在末尾。也可在命令面板（Ctrl+K）中使用：通用聊天。在第一个通用聊天之前，会有一个窗口列出聊天能看到组织的哪些仓库：在文件夹内找到的每个克隆都算在内，即使它在这台计算机上不是项目。"$json$::jsonb),
  ('hi', 'docs.orgChat.usage', $json$"संगठन के परिवेश में, सामान्य चैट की सूची खोलने या बंद करने के लिए साइड मेनू में चैट पर क्लिक करें, सबसे नई पहले: किसी एक पर क्लिक करके उसे जारी रखें या + से दूसरी शुरू करें। प्रोजेक्ट के ऊपर का चैट खोलें बटन भी एक चुनने या शुरू करने देता है। इस कंप्यूटर पर संगठन का फ़ोल्डर न हो तो JayV पहले एक माँगता है। किसी सामान्य चैट में, कोड पैनल का रिपॉज़िटरी टैब फ़ोल्डर के हर रिपॉज़िटरी का git status और उसकी LLM नीति कहाँ से आती है, यह दिखाता है; संगठन के जो रिपॉज़िटरी फ़ोल्डर में नहीं हैं, वे अंत में दिखते हैं। कमांड पैलेट (Ctrl+K) में भी: सामान्य चैट। पहली सामान्य चैट से पहले एक विंडो दिखाती है कि चैट संगठन की किन रिपॉज़िटरी को देखती है: फ़ोल्डर के अंदर मिला हर क्लोन गिना जाता है, भले ही वह इस कंप्यूटर पर प्रोजेक्ट न हो।"$json$::jsonb),
  ('ar', 'docs.orgChat.usage', $json$"في بيئة المؤسسة، انقر «المحادثات» في القائمة الجانبية لفتح قائمة المحادثات العامة أو إغلاقها، والأحدث أولًا: انقر إحداها لمتابعتها أو + لبدء أخرى. ويتيح زر «فتح الدردشة» أعلى المشاريع أيضًا اختيار محادثة أو بدء واحدة. إن لم يكن على هذا الجهاز مجلد للمؤسسة، يطلب JayV واحدًا أولًا. في المحادثة العامة، يعرض تبويب «المستودعات» في لوحة «الشيفرة» حالة git لكل مستودع في المجلد ومن أين تأتي سياسة LLM الخاصة به؛ وتظهر مستودعات المؤسسة غير الموجودة في المجلد في النهاية. وأيضًا في لوحة الأوامر (Ctrl+K): المحادثات العامة. قبل أول محادثة عامة، تعرض نافذة مستودعات المؤسسة التي تراها المحادثة: يُحتسب كل نسخ مستنسخ يُعثر عليه داخل المجلد، حتى لو لم يكن مشروعًا على هذا الحاسوب."$json$::jsonb),
  ('fr', 'docs.orgChat.usage', $json$"Dans l’environnement de l’organisation, cliquez sur Chats dans le menu latéral pour ouvrir ou fermer la liste des chats généraux, du plus récent au plus ancien : cliquez sur l’un pour le reprendre ou sur + pour en lancer un autre. Le bouton Ouvrir le chat en haut de Projets permet aussi d’en choisir ou d’en lancer un. Sans dossier de l’organisation sur cet ordinateur, JayV en demande un d’abord. Dans un chat général, l’onglet Dépôts du panneau Code montre le git status de chaque dépôt du dossier et d’où vient sa politique LLM ; les dépôts de l’organisation absents du dossier apparaissent à la fin. Aussi dans la palette de commandes (Ctrl+K) : Chats généraux. Avant le premier chat général, une fenêtre indique quels dépôts de l’organisation le chat voit : chaque clone trouvé dans le dossier compte, même s’il n’est pas un projet sur cet ordinateur."$json$::jsonb),
  ('ru', 'docs.orgChat.usage', $json$"В среде организации нажмите «Чаты» в боковом меню, чтобы открыть или закрыть список общих чатов, сначала самые новые: нажмите на чат, чтобы продолжить его, или на +, чтобы начать новый. Кнопка «Открыть чат» вверху страницы «Проекты» тоже позволяет выбрать или начать чат. Если на этом компьютере нет папки организации, JayV сначала попросит её указать. В общем чате вкладка «Репозитории» панели «Код» показывает git status каждого репозитория папки и откуда берётся его политика LLM; репозитории организации, которых нет в папке, показаны в конце. Также в палитре команд (Ctrl+K): «Общие чаты». Перед первым общим чатом окно показывает, какие репозитории организации видит чат: учитывается каждый клон, найденный внутри папки, даже если на этом компьютере он не является проектом."$json$::jsonb),
  ('ja', 'docs.orgChat.usage', $json$"組織の環境で、サイドメニューの「チャット」をクリックすると総合チャットの一覧を開閉できます（新しい順）。クリックすると続きから、+ で新しく始められます。プロジェクト上部の「チャットを開く」ボタンからも選んだり始めたりできます。このコンピューターに組織のフォルダーがない場合、JayV が先に指定を求めます。総合チャットでは、「コード」パネルの「リポジトリ」タブに、フォルダー内の各リポジトリの git status と LLM ポリシーの出どころが表示され、フォルダーにない組織のリポジトリは最後に表示されます。コマンドパレット（Ctrl+K）の「総合チャット」からも使えます。最初の総合チャットの前に、チャットから見える組織のリポジトリを一覧するウィンドウが出ます。フォルダー内で見つかったクローンは、このコンピューターでプロジェクトになっていなくてもすべて含まれます。"$json$::jsonb),
  ('de', 'docs.orgChat.usage', $json$"Klicken Sie in der Umgebung der Organisation im Seitenmenü auf Chats, um die Liste der allgemeinen Chats zu öffnen oder zu schließen, die neuesten zuerst: Klicken Sie auf einen, um ihn fortzusetzen, oder auf +, um einen weiteren zu starten. Auch die Schaltfläche Chat öffnen oben in Projekte lässt einen wählen oder starten. Ohne Ordner der Organisation auf diesem Computer fragt JayV zuerst nach einem. In einem allgemeinen Chat zeigt der Tab Repositorys des Code-Panels den Git-Status jedes Repositorys im Ordner und woher seine LLM-Richtlinie stammt; die Repositorys der Organisation, die nicht im Ordner liegen, erscheinen am Ende. Auch in der Befehlspalette (Ctrl+K): Allgemeine Chats. Vor dem ersten allgemeinen Chat zeigt ein Fenster, welche Repositorys der Organisation der Chat sieht: Jeder Klon im Ordner zählt, auch wenn er auf diesem Computer kein Projekt ist."$json$::jsonb),
  ('pt-BR', 'docs.mcp.usage', $json$"Abra Configurações › MCP (ou Ctrl+K › Configurações › MCP) e adicione um servidor pelo formulário ou cole uma configuração (JSON mcpServers, uma linha claude mcp add ou um comando npx). No chat, digite /mcp seguido de uma configuração ou de uma descrição: um agente monta o rascunho e nada é salvo antes de você conferir e clicar em Salvar configuração. Ligar, desligar, editar, adicionar ou remover um servidor só vale ao clicar em Salvar configuração; Descartar desfaz a mudança. Os servidores de uma organização não aparecem aqui, e sim em MCP, no ambiente dela. Depois ligue Aprovar servidores MCP na aba de cada agente que deve usá-los (começa desligado); Ctrl+K › Aprovar servidores MCP faz o mesmo para um agente. As organizações podem bloquear por agente, e o modo planejamento nunca leva os servidores. Quatro servidores oficiais (sequential-thinking, fetch, git e memory) já vêm cadastrados, como entradas que você pode desligar, editar ou remover; fetch e git rodam pelo uvx, então o uv precisa estar instalado. Nos chats de uma organização (o geral e os de cada projeto), os servidores dela valem por cima dos seus com o mesmo nome, mesmo quando a organização desliga um. O rascunho do /mcp vem na hora, mesmo com outro pedido rodando."$json$::jsonb),
  ('en', 'docs.mcp.usage', $json$"Open Settings › MCP (or Ctrl+K › Settings › MCP) and add a server by form, or paste a configuration (mcpServers JSON, a claude mcp add line or an npx command). In a chat, type /mcp followed by a configuration or a description: an agent drafts the configuration and nothing is saved until you review it and click Save settings. Four official servers (sequential-thinking, fetch, git and memory) come registered, as entries you can turn off, edit or remove; fetch and git run through uvx, so uv must be installed. Turning a server on or off, editing, adding or removing it takes effect only when you click Save settings; Discard drops the change. Servers of an organization are not listed here but under MCP in that organization’s environment; in its chats (the general one and each project’s) they win over yours with the same name, even when the organization turns one off. Then turn on Approve MCP servers in the Settings tab of each agent that should use them (it starts off); Ctrl+K › Approve MCP servers does the same for one agent. Organizations can block it per agent, and planning mode never carries the servers. The /mcp draft comes right away even while another request is running."$json$::jsonb),
  ('es', 'docs.mcp.usage', $json$"Abre Configuración › MCP (o Ctrl+K › Configuración › MCP) y añade un servidor con el formulario o pega una configuración (JSON mcpServers, una línea claude mcp add o un comando npx). En un chat, escribe /mcp seguido de una configuración o una descripción: un agente prepara el borrador y no se guarda nada hasta que lo revises y hagas clic en Guardar configuración. Activar, desactivar, editar, añadir o eliminar un servidor solo vale al hacer clic en Guardar configuración; Descartar deshace el cambio. Los servidores de una organización no aparecen aquí, sino en MCP, en el entorno de esa organización. Después activa Aprobar servidores MCP en la pestaña de cada agente que deba usarlos (empieza desactivado); Ctrl+K › Aprobar servidores MCP hace lo mismo para un agente. Las organizaciones pueden bloquearlo por agente, y el modo de planificación nunca lleva los servidores. Cuatro servidores oficiales (sequential-thinking, fetch, git y memory) vienen ya registrados, como entradas que puedes desactivar, editar o eliminar; fetch y git se ejecutan con uvx, así que uv debe estar instalado. En los chats de una organización (el general y los de cada proyecto), sus servidores tienen prioridad sobre los tuyos con el mismo nombre, incluso cuando la organización desactiva uno. El borrador de /mcp llega de inmediato, incluso con otra solicitud en curso."$json$::jsonb),
  ('zh-CN', 'docs.mcp.usage', $json$"打开“设置 › MCP”（或 Ctrl+K › 设置 › MCP），通过表单添加服务器，或粘贴配置（mcpServers JSON、claude mcp add 命令行或 npx 命令）。在聊天中输入 /mcp，后面跟配置或描述：代理会生成草稿，在你确认并点击“保存设置”之前不会保存任何内容。开启、关闭、编辑、添加或删除服务器，只有点击“保存设置”后才会生效；“放弃更改”会撤销改动。组织的服务器不在这里显示，而是在该组织环境的 MCP 中。然后在每个要使用它们的代理的设置标签页中开启“批准 MCP 服务器”（默认关闭）；Ctrl+K › 批准 MCP 服务器可对单个代理执行同样的操作。组织可以按代理屏蔽它，规划模式永远不会带上这些服务器。四个官方服务器（sequential-thinking、fetch、git 和 memory）已预先注册，是可以关闭、编辑或删除的普通条目；fetch 和 git 通过 uvx 运行，因此需要安装 uv。在组织的聊天（通用聊天和各项目的聊天）中，组织的服务器优先于你的同名服务器，即使组织将其关闭也一样。即使有其他请求正在运行，/mcp 的草稿也会立即生成。"$json$::jsonb),
  ('hi', 'docs.mcp.usage', $json$"सेटिंग › MCP खोलें (या Ctrl+K › सेटिंग › MCP) और फ़ॉर्म से सर्वर जोड़ें या कॉन्फ़िगरेशन चिपकाएँ (mcpServers JSON, claude mcp add पंक्ति या npx कमांड)। चैट में /mcp के बाद कॉन्फ़िगरेशन या विवरण लिखें: एजेंट मसौदा बनाता है और आपके जाँचने और सेटिंग्स सहेजें पर क्लिक करने से पहले कुछ भी सहेजा नहीं जाता। किसी सर्वर को चालू, बंद, संपादित करना, जोड़ना या हटाना सेटिंग्स सहेजें पर क्लिक करने पर ही लागू होता है; बदलाव छोड़ें बदलाव को रद्द करता है। किसी संगठन के सर्वर यहाँ नहीं दिखते, बल्कि उस संगठन के परिवेश में MCP में दिखते हैं। फिर हर उस एजेंट के सेटिंग टैब में MCP सर्वर स्वीकृत करें चालू करें जिसे इन्हें इस्तेमाल करना है (यह बंद से शुरू होता है); Ctrl+K › MCP सर्वर स्वीकृत करें एक एजेंट के लिए यही करता है। संगठन इसे हर एजेंट के लिए अवरुद्ध कर सकते हैं, और योजना मोड कभी सर्वर नहीं ले जाता। चार आधिकारिक सर्वर (sequential-thinking, fetch, git और memory) पहले से रजिस्टर आते हैं, सामान्य प्रविष्टियों के रूप में जिन्हें आप बंद, संपादित या हटा सकते हैं; fetch और git uvx से चलते हैं, इसलिए uv इंस्टॉल होना चाहिए। किसी संगठन की चैट में (सामान्य चैट और हर प्रोजेक्ट की चैट) संगठन के सर्वर आपके उसी नाम वाले सर्वर पर भारी पड़ते हैं, भले ही संगठन उसे बंद कर दे। दूसरा अनुरोध चलते समय भी /mcp का ड्राफ़्ट तुरंत आता है।"$json$::jsonb),
  ('ar', 'docs.mcp.usage', $json$"افتح الإعدادات › MCP (أو Ctrl+K › الإعدادات › MCP) وأضف خادمًا بالنموذج أو الصق إعدادًا (JSON من mcpServers أو سطر claude mcp add أو أمر npx). في المحادثة اكتب ‎/mcp‎ متبوعًا بإعداد أو وصف: يُعدّ الوكيل مسودة ولا يُحفظ شيء قبل أن تراجعه وتنقر «حفظ الإعدادات». لا يسري تشغيل خادم أو إيقافه أو تعديله أو إضافته أو إزالته إلا عند النقر على «حفظ الإعدادات»؛ و«تجاهل التغييرات» يلغي التغيير. لا تظهر خوادم المؤسسة هنا، بل في MCP ضمن بيئة تلك المؤسسة. ثم فعّل «الموافقة على خوادم MCP» في تبويب كل وكيل يجب أن يستخدمها (يبدأ متوقفًا)؛ وCtrl+K › الموافقة على خوادم MCP يفعل الشيء نفسه لوكيل واحد. يمكن للمؤسسات حجبه لكل وكيل، ولا يحمل وضع التخطيط الخوادم أبدًا. تأتي أربعة خوادم رسمية (sequential-thinking وfetch وgit وmemory) مسجَّلة مسبقًا، كإدخالات عادية يمكنك إيقافها أو تعديلها أو إزالتها؛ يعمل fetch وgit عبر uvx، لذا يجب تثبيت uv. في محادثات المؤسسة (العامة ومحادثات كل مشروع) تتقدّم خوادم المؤسسة على خوادمك التي تحمل الاسم نفسه، حتى لو أوقفت المؤسسة أحدها. تصل مسودة /mcp فورًا، حتى أثناء تنفيذ طلب آخر."$json$::jsonb),
  ('fr', 'docs.mcp.usage', $json$"Ouvrez Paramètres › MCP (ou Ctrl+K › Paramètres › MCP) et ajoutez un serveur par le formulaire ou collez une configuration (JSON mcpServers, une ligne claude mcp add ou une commande npx). Dans un chat, tapez /mcp suivi d’une configuration ou d’une description : un agent prépare le brouillon et rien n’est enregistré avant votre vérification et un clic sur Enregistrer la configuration. Activer, désactiver, modifier, ajouter ou supprimer un serveur ne prend effet qu’au clic sur Enregistrer la configuration ; Annuler les modifications défait le changement. Les serveurs d’une organisation n’apparaissent pas ici, mais dans MCP, dans l’environnement de cette organisation. Activez ensuite Approuver les serveurs MCP dans l’onglet de chaque agent qui doit les utiliser (désactivé au départ) ; Ctrl+K › Approuver les serveurs MCP fait de même pour un agent. Les organisations peuvent le bloquer par agent, et le mode planification ne transporte jamais les serveurs. Quatre serveurs officiels (sequential-thinking, fetch, git et memory) sont déjà enregistrés, comme des entrées ordinaires que vous pouvez désactiver, modifier ou supprimer ; fetch et git passent par uvx, donc uv doit être installé. Dans les conversations d’une organisation (la générale et celles de chaque projet), ses serveurs l’emportent sur les vôtres de même nom, même lorsque l’organisation en désactive un. Le brouillon de /mcp arrive tout de suite, même pendant qu’une autre demande s’exécute."$json$::jsonb),
  ('ru', 'docs.mcp.usage', $json$"Откройте «Настройки › MCP» (или Ctrl+K › Настройки › MCP) и добавьте сервер через форму либо вставьте конфигурацию (JSON mcpServers, строку claude mcp add или команду npx). В чате введите /mcp, а затем конфигурацию или описание: агент подготовит черновик, и ничего не сохранится, пока вы его не проверите и не нажмёте «Сохранить настройки». Включение, выключение, изменение, добавление или удаление сервера вступает в силу только после нажатия «Сохранить настройки»; «Отменить» отбрасывает изменение. Серверы организации здесь не показываются — они в разделе MCP в среде этой организации. Затем включите «Одобрять серверы MCP» на вкладке каждого агента, который должен их использовать (по умолчанию выключено); Ctrl+K › Одобрять серверы MCP делает то же для одного агента. Организации могут блокировать это по агентам, а режим планирования никогда не берёт серверы. Четыре официальных сервера (sequential-thinking, fetch, git и memory) уже зарегистрированы как обычные записи: их можно выключить, изменить или удалить; fetch и git запускаются через uvx, поэтому должен быть установлен uv. В чатах организации (общем и в чатах каждого проекта) её серверы имеют приоритет над вашими с тем же именем, даже если организация выключила сервер. Черновик /mcp появляется сразу, даже пока выполняется другой запрос."$json$::jsonb),
  ('ja', 'docs.mcp.usage', $json$"設定 › MCP（または Ctrl+K › 設定 › MCP）を開き、フォームでサーバーを追加するか、設定（mcpServers の JSON、claude mcp add の行、npx コマンド）を貼り付けます。チャットでは /mcp に続けて設定または説明を入力します。エージェントが下書きを作り、確認して「設定を保存」をクリックするまで何も保存されません。サーバーのオン／オフ、編集、追加、削除は「設定を保存」をクリックしたときにだけ反映され、「破棄」で変更を取り消せます。組織のサーバーはここには表示されず、その組織の環境の MCP にあります。そのあと、使わせたい各エージェントの設定タブで「MCP サーバーを承認」をオンにします（初期値はオフ）。Ctrl+K › MCP サーバーを承認 で1つのエージェントに対して同じことができます。組織はエージェントごとにブロックでき、計画モードではサーバーは渡されません。 公式サーバー 4 つ（sequential-thinking、fetch、git、memory）が最初から登録されています。通常のエントリなので、オフにしたり編集したり削除したりできます。fetch と git は uvx で動くため、uv のインストールが必要です。組織のチャット（全体用と各プロジェクト用）では、同じ名前なら組織のサーバーがあなたのものより優先されます。組織がそのサーバーをオフにしている場合も同じです。別の依頼の実行中でも、/mcp の下書きはすぐに届きます。"$json$::jsonb),
  ('de', 'docs.mcp.usage', $json$"Öffnen Sie Einstellungen › MCP (oder Strg+K › Einstellungen › MCP) und fügen Sie einen Server über das Formular hinzu oder fügen Sie eine Konfiguration ein (mcpServers-JSON, eine claude-mcp-add-Zeile oder einen npx-Befehl). Geben Sie im Chat /mcp gefolgt von einer Konfiguration oder Beschreibung ein: Ein Agent erstellt den Entwurf, und nichts wird gespeichert, bevor Sie ihn geprüft und auf Einstellungen speichern geklickt haben. Einen Server ein- oder ausschalten, bearbeiten, hinzufügen oder entfernen wirkt erst mit einem Klick auf Einstellungen speichern; Verwerfen macht die Änderung rückgängig. Die Server einer Organisation stehen nicht hier, sondern unter MCP in der Umgebung dieser Organisation. Schalten Sie danach „MCP-Server freigeben“ im Einstellungs-Tab jedes Agenten ein, der sie nutzen soll (standardmäßig aus); Strg+K › MCP-Server freigeben macht dasselbe für einen Agenten. Organisationen können es je Agent sperren, und der Planungsmodus trägt die Server nie. Vier offizielle Server (sequential-thinking, fetch, git und memory) sind bereits eingetragen, als normale Einträge, die Sie ausschalten, bearbeiten oder entfernen können; fetch und git laufen über uvx, daher muss uv installiert sein. In den Chats einer Organisation (dem allgemeinen und denen jedes Projekts) haben deren Server Vorrang vor Ihren gleichnamigen, auch wenn die Organisation einen ausschaltet. Der Entwurf von /mcp kommt sofort, auch während eine andere Anfrage läuft."$json$::jsonb),
  ('pt-BR', 'docs.modCatalog.usage', $json$"Abra Configuração › Mods. Cada mod mostra o seu ícone. Em Instalados, ligue ou desligue cada mod, abra a configuração dele ou desinstale-o; em Disponíveis no catálogo, Instalar adiciona um mod (e os mods de que ele precisa). A busca filtra as duas listas pelo nome, pela descrição ou pelo autor. Os mods essenciais — os recursos do app — ficam sempre instalados e ligados, sem interruptor nem Desinstalar; os motores de LLM, os agentes (como Ollama e LM Studio) e as skills (como o REA) podem ser desligados e desinstalados. As mudanças valem quando você salva, neste ambiente e nos seus outros computadores; o site (Painel › Mods) mostra e muda os mesmos mods. Um mod que veio instalado não volta sozinho depois de desinstalado. Um mod que precisa de um JayV mais novo espera a atualização. O plano continua decidindo: o que ele não inclui fica desligado, e o que ele trava fica ligado. O botão do livro de cada mod abre a página dele no site. Também na paleta de comandos (Ctrl+K): Instalar mod, Ligar mod, Desligar mod, Desinstalar mod e Página do mod no site. Se outro computador ou o site mudar os mods enquanto você tem alterações não salvas aqui, salvar aplica só o que você mudou na aba."$json$::jsonb),
  ('en', 'docs.modCatalog.usage', $json$"Open Settings › Mods. Each mod shows its icon. Under Installed, turn each mod on or off, open its settings or uninstall it; under Available in the catalog, Install adds a mod (and the mods it needs). Search filters both lists by name, description or author. The essential mods — the features of the app — always stay installed and on, without a switch or Uninstall; the LLM engines, the agents (like Ollama and LM Studio) and the skills (like REA) can be turned off and uninstalled. The changes apply when you save, in this environment and on your other computers; the site (Dashboard › Mods) shows and changes the same mods. A mod that came installed does not come back on its own after you uninstall it. A mod that needs a newer JayV waits for the update. Your plan still decides: what it doesn't include stays off, and what it locks stays on. The book button of each mod opens its page on the site. Also in the command palette (Ctrl+K): Install mod, Turn on mod, Turn off mod, Uninstall mod and Mod page on the site. If another computer or the site changes the mods while you have unsaved changes here, saving applies only what you changed in the tab."$json$::jsonb),
  ('es', 'docs.modCatalog.usage', $json$"Abre Configuración › Mods. Cada mod muestra su icono. En Instalados, activa o desactiva cada mod, abre su configuración o desinstálalo; en Disponibles en el catálogo, Instalar añade un mod (y los mods que necesita). La búsqueda filtra ambas listas por nombre, descripción o autor. Los mods esenciales — las funciones de la app — siempre se quedan instalados y activados, sin interruptor ni Desinstalar; los motores de LLM, los agentes (como Ollama y LM Studio) y las skills (como REA) se pueden desactivar y desinstalar. Los cambios valen al guardar, en este entorno y en tus otros equipos; el sitio (Panel › Mods) muestra y cambia los mismos mods. Un mod que vino instalado no vuelve solo después de desinstalarlo. Un mod que necesita un JayV más reciente espera la actualización. Tu plan sigue decidiendo: lo que no incluye queda desactivado y lo que bloquea queda activado. El botón del libro de cada mod abre su página en el sitio. También en la paleta de comandos (Ctrl+K): Instalar mod, Activar mod, Desactivar mod, Desinstalar mod y Página del mod en el sitio. Si otro equipo o el sitio cambia los mods mientras tienes cambios sin guardar aquí, al guardar se aplica solo lo que cambiaste en la pestaña."$json$::jsonb),
  ('zh-CN', 'docs.modCatalog.usage', $json$"打开“设置 › 模组”。每个模组都会显示自己的图标。在“已安装”中开启或关闭每个模组、打开其设置或卸载；在“目录中可用”中，“安装”会添加一个模组（以及它依赖的模组）。搜索可按名称、描述或作者筛选两个列表。必需模组（即应用的功能）始终保持安装并开启，没有开关也没有“卸载”；LLM 引擎、代理（如 Ollama 和 LM Studio）和技能（如 REA）可以关闭和卸载。保存后，更改在此环境和你的其他电脑上生效；网站（控制台 › 模组）显示并修改相同的模组。预装的模组卸载后不会自动回来。需要更新版 JayV 的模组会等待更新。套餐仍然决定一切：不包含的保持关闭，锁定的保持开启。每个模组的书本按钮会打开它在网站上的页面。命令面板（Ctrl+K）中也有：安装模组、开启模组、关闭模组、卸载模组和网站上的模组页面。如果在你这里有未保存的更改时，另一台计算机或网站更改了模组，保存时只会应用你在该标签页中所做的更改。"$json$::jsonb),
  ('hi', 'docs.modCatalog.usage', $json$"सेटिंग्स › मॉड खोलें। हर मॉड अपना आइकन दिखाता है। इंस्टॉल किए गए में हर मॉड को चालू या बंद करें, उसकी सेटिंग खोलें या उसे अनइंस्टॉल करें; कैटलॉग में उपलब्ध में, इंस्टॉल करें एक मॉड (और उसे चाहिए मॉड) जोड़ता है। खोज दोनों सूचियों को नाम, विवरण या लेखक से छाँटती है। ज़रूरी मॉड — ऐप की सुविधाएँ — हमेशा इंस्टॉल और चालू रहते हैं, बिना स्विच और बिना अनइंस्टॉल के; LLM इंजन, एजेंट (जैसे Ollama और LM Studio) और स्किल (जैसे REA) बंद और अनइंस्टॉल किए जा सकते हैं। बदलाव सहेजने पर इस वातावरण और आपके दूसरे कंप्यूटरों पर लागू होते हैं; साइट (डैशबोर्ड › मॉड) वही मॉड दिखाती और बदलती है। पहले से इंस्टॉल आया मॉड अनइंस्टॉल करने के बाद अपने-आप वापस नहीं आता। जिस मॉड को JayV का नया संस्करण चाहिए वह अपडेट का इंतज़ार करता है। आपका प्लान अब भी तय करता है: जो उसमें शामिल नहीं वह बंद रहता है, और जो वह लॉक करता है वह चालू रहता है। हर मॉड का किताब वाला बटन साइट पर उसका पेज खोलता है। कमांड पैलेट (Ctrl+K) में भी: मॉड इंस्टॉल करें, मॉड चालू करें, मॉड बंद करें, मॉड अनइंस्टॉल करें और साइट पर मॉड का पेज। अगर यहाँ आपके बिना सहेजे बदलाव रहते हुए कोई दूसरा कंप्यूटर या साइट मॉड बदल दे, तो सहेजने पर सिर्फ़ वही लागू होता है जो आपने टैब में बदला।"$json$::jsonb),
  ('ar', 'docs.modCatalog.usage', $json$"افتح الإعدادات › الإضافات. تعرض كل إضافة أيقونتها. في المثبّتة، فعّل كل إضافة أو عطّلها، أو افتح إعداداتها أو ألغِ تثبيتها؛ وفي المتاحة في الفهرس، يضيف «تثبيت» إضافةً (والإضافات التي تحتاج إليها). يصفّي البحث القائمتين بالاسم أو الوصف أو المؤلف. تبقى الإضافات الأساسية — وهي ميزات التطبيق — مثبّتة ومفعّلة دائمًا، بلا مفتاح ولا «إلغاء التثبيت»؛ أما محركات LLM والوكلاء (مثل Ollama وLM Studio) والمهارات (مثل REA) فيمكن تعطيلها وإلغاء تثبيتها. تسري التغييرات عند الحفظ، في هذه البيئة وعلى أجهزتك الأخرى؛ ويعرض الموقع (لوحة التحكم › الإضافات) الإضافات نفسها ويغيّرها. الإضافة التي جاءت مثبّتة لا تعود وحدها بعد إلغاء تثبيتها. والإضافة التي تحتاج إلى إصدار أحدث من JayV تنتظر التحديث. تظل خطتك هي الحاكمة: ما لا تتضمنه يبقى معطّلًا، وما تقفله يبقى مفعّلًا. يفتح زر الكتاب في كل إضافة صفحتها على الموقع. وفي لوحة الأوامر (Ctrl+K) أيضًا: تثبيت الإضافة، وتفعيل الإضافة، وتعطيل الإضافة، وإلغاء تثبيت الإضافة، وصفحة الإضافة على الموقع. إذا غيّر حاسوب آخر أو الموقع الإضافات بينما لديك تغييرات غير محفوظة هنا، فإن الحفظ يطبّق فقط ما غيّرته في التبويب."$json$::jsonb),
  ('fr', 'docs.modCatalog.usage', $json$"Ouvrez Configuration › Mods. Chaque mod affiche son icône. Dans Installés, activez ou désactivez chaque mod, ouvrez ses réglages ou désinstallez-le ; dans Disponibles dans le catalogue, Installer ajoute un mod (et les mods dont il a besoin). La recherche filtre les deux listes par nom, description ou auteur. Les mods essentiels — les fonctionnalités de l’app — restent toujours installés et activés, sans interrupteur ni Désinstaller ; les moteurs LLM, les agents (comme Ollama et LM Studio) et les skills (comme REA) peuvent être désactivés et désinstallés. Les changements s’appliquent à l’enregistrement, dans cet environnement et sur vos autres ordinateurs ; le site (Tableau de bord › Mods) affiche et modifie les mêmes mods. Un mod fourni installé ne revient pas tout seul après sa désinstallation. Un mod qui demande un JayV plus récent attend la mise à jour. Votre forfait décide toujours : ce qu’il n’inclut pas reste désactivé, et ce qu’il verrouille reste activé. Le bouton du livre de chaque mod ouvre sa page sur le site. Aussi dans la palette de commandes (Ctrl+K) : Installer le mod, Activer le mod, Désactiver le mod, Désinstaller le mod et Page du mod sur le site. Si un autre ordinateur ou le site modifie les mods pendant que vous avez des changements non enregistrés ici, l’enregistrement n’applique que ce que vous avez changé dans l’onglet."$json$::jsonb),
  ('ru', 'docs.modCatalog.usage', $json$"Откройте Настройки › Моды. У каждого мода видна его иконка. В разделе «Установленные» включайте и выключайте каждый мод, открывайте его настройки или удаляйте его; в разделе «Доступно в каталоге» кнопка «Установить» добавляет мод (и нужные ему моды). Поиск фильтрует оба списка по названию, описанию или автору. Обязательные моды — функции приложения — всегда установлены и включены, без переключателя и без «Удалить»; движки LLM, агентов (например, Ollama и LM Studio) и скиллы (например, REA) можно выключать и удалять. Изменения вступают в силу после сохранения — в этом окружении и на других ваших компьютерах; сайт (Панель › Моды) показывает и меняет те же моды. Предустановленный мод после удаления сам не возвращается. Мод, которому нужна более новая версия JayV, ждёт обновления. Тариф по-прежнему решает: то, чего в нём нет, остаётся выключенным, а то, что он закрепляет, — включённым. Кнопка с книгой у каждого мода открывает его страницу на сайте. Также в палитре команд (Ctrl+K): «Установить мод», «Включить мод», «Выключить мод», «Удалить мод» и «Страница мода на сайте». Если другой компьютер или сайт изменит моды, пока у вас здесь есть несохранённые изменения, при сохранении применяется только то, что вы изменили на вкладке."$json$::jsonb),
  ('ja', 'docs.modCatalog.usage', $json$"設定 › Mod を開きます。各 Mod にはアイコンが表示されます。「インストール済み」では各 Mod のオン／オフ、設定の表示、アンインストールができます。「カタログで利用可能」では「インストール」で Mod（と必要な Mod）を追加します。検索で両方の一覧を名前、説明、作者で絞り込めます。必須の Mod（アプリの機能）は常にインストール済みでオンのままで、スイッチも「アンインストール」もありません。LLM エンジン、エージェント（Ollama や LM Studio など）、スキル（REA など）はオフやアンインストールができます。変更は保存したときに、この環境とほかのコンピューターに反映されます。サイト（ダッシュボード › Mod）でも同じ Mod を表示・変更できます。最初からインストールされていた Mod は、アンインストールすると自動では戻りません。より新しい JayV が必要な Mod はアップデートを待ちます。プランは引き続き適用され、含まれないものはオフ、固定されたものはオンのままです。各 Mod の本のボタンでサイトのページが開きます。コマンドパレット（Ctrl+K）でも「Mod をインストール」「Mod をオン」「Mod をオフ」「Mod をアンインストール」「サイトの Mod ページ」が使えます。ここに未保存の変更がある間に別のコンピューターやサイトが Mod を変更しても、保存時に適用されるのはタブであなたが変更した内容だけです。"$json$::jsonb),
  ('de', 'docs.modCatalog.usage', $json$"Öffnen Sie Einstellungen › Mods. Jeder Mod zeigt sein Symbol. Unter „Installiert“ schalten Sie jeden Mod ein oder aus, öffnen seine Einstellungen oder deinstallieren ihn; unter „Im Katalog verfügbar“ fügt „Installieren“ einen Mod (und die Mods, die er benötigt) hinzu. Die Suche filtert beide Listen nach Name, Beschreibung oder Autor. Die unverzichtbaren Mods – die Funktionen der App – bleiben immer installiert und eingeschaltet, ohne Schalter und ohne „Deinstallieren“; die LLM-Engines, die Agenten (wie Ollama und LM Studio) und die Skills (wie REA) lassen sich ausschalten und deinstallieren. Änderungen gelten beim Speichern, in dieser Umgebung und auf Ihren anderen Computern; die Website (Dashboard › Mods) zeigt und ändert dieselben Mods. Ein vorinstallierter Mod kommt nach dem Deinstallieren nicht von selbst zurück. Ein Mod, der ein neueres JayV benötigt, wartet auf das Update. Ihr Tarif entscheidet weiterhin: Was er nicht enthält, bleibt aus, und was er sperrt, bleibt an. Die Buch-Schaltfläche jedes Mods öffnet seine Seite auf der Website. Auch in der Befehlspalette (Strg+K): Mod installieren, Mod einschalten, Mod ausschalten, Mod deinstallieren und Mod-Seite auf der Website. Ändert ein anderer Computer oder die Website die Mods, während Sie hier ungespeicherte Änderungen haben, wird beim Speichern nur übernommen, was Sie im Tab geändert haben."$json$::jsonb)
